CREATE TABLE result(a,b,k,v,g1,g2,g3,g4,g5,g6,g7,g8,g9); INSERT INTO result(a,b,k,v,g1,g2,g3,g4,g5,g6,g7,g8,g9) SELECT * FROM (SELECT * FROM t1, t3), (SELECT group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a), group_concat(a) OVER (ORDER BY a) FROM t1) ORDER BY k;